addword('sortez','fr:sortez:exit-request','sortez','выйдите (короткая инструкция)','сортэ́',ex('Sortez, s’il vous plaît.','Выйдите, пожалуйста.','сортэ, силь ву плэ́'),1,[rev('sortez-meaning',fr('Sortez !','сортэ́'),['Выйдите','Войдите','Пожалуйста'],0,'Это инструкция выйти.','Нужно выйти; вход и формула пожалуйста имеют другой смысл.'),rev('sortez-use',ru('В условии нужно попросить собеседника выйти. Какую реплику выбрать?'),[fr('Entrez, s’il vous plaît.','а(н)трэ, силь ву плэ́'),fr('Sortez, s’il vous plaît.','сортэ, силь ву плэ́'),fr('Bonjour !','бо(н)жу́р')],1,'Выбрана просьба выйти.','Нужна инструкция выйти; вход и приветствие не соответствуют условию.')])
