addword('porte','fr:porte:door','une porte','дверь','юн по́рт',ex('Ouvrez la porte.','Откройте дверь.','уврэ ла по́рт'),2,[rev('porte-meaning',fr('Une porte','юн по́рт'),['Стул','Дверь','Окно'],1,'Названа дверь.','Правильное значение — дверь; стул и окно обозначают другие предметы.'),rev('porte-use',ru('Какое сочетание называет дверь, которую нужно открыть?'),[fr('Une fenêtre','юн фёнэ́тр'),fr('Une chaise','юн шэ́з'),fr('Une porte','юн по́рт')],2,'Выбрано название двери.','Нужна дверь; окно и стул не соответствуют условию.')])
